CREATE DATABASE IF NOT EXISTS ubuntusure CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ubuntusure;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS claim_assessments; DROP TABLE IF EXISTS claims; DROP TABLE IF EXISTS motor_policy_details; DROP TABLE IF EXISTS property_policy_details; DROP TABLE IF EXISTS life_policy_details; DROP TABLE IF EXISTS health_policy_details; DROP TABLE IF EXISTS policies; DROP TABLE IF EXISTS customers; DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users (user_id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password_hash CHAR(64) NOT NULL, role ENUM('INSURANCE_OFFICER','CLAIMS_OFFICER','ADMINISTRATOR') NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customers (customer_id INT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(80) NOT NULL, surname VARCHAR(80) NOT NULL, national_id VARCHAR(80) NOT NULL UNIQUE, date_of_birth DATE NULL, gender VARCHAR(30), phone VARCHAR(30) NOT NULL, email VARCHAR(150), physical_address VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE policies (policy_id INT AUTO_INCREMENT PRIMARY KEY, policy_number VARCHAR(40) NOT NULL UNIQUE, customer_id INT NOT NULL, product_type ENUM('MOTOR','PROPERTY','LIFE','HEALTH') NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, coverage_amount DECIMAL(14,2) NOT NULL, annual_premium DECIMAL(12,2) NOT NULL, status ENUM('PENDING','ACTIVE','EXPIRED','CANCELLED') NOT NULL DEFAULT 'PENDING', created_by INT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_policy_customer FOREIGN KEY(customer_id) REFERENCES customers(customer_id), CONSTRAINT fk_policy_user FOREIGN KEY(created_by) REFERENCES users(user_id), CONSTRAINT chk_policy_coverage CHECK(coverage_amount>0), CONSTRAINT chk_policy_premium CHECK(annual_premium>=0), CONSTRAINT chk_policy_dates CHECK(start_date<=end_date));
CREATE TABLE motor_policy_details (policy_id INT PRIMARY KEY, vehicle_registration VARCHAR(30) NOT NULL, make VARCHAR(60) NOT NULL, model VARCHAR(60) NOT NULL, vehicle_year SMALLINT NOT NULL, vehicle_value DECIMAL(14,2) NOT NULL, vehicle_type ENUM('Private Car','Minibus','Truck','Motorcycle') NOT NULL, cover_type ENUM('Third Party','Comprehensive') NOT NULL, FOREIGN KEY(policy_id) REFERENCES policies(policy_id) ON DELETE CASCADE, CHECK(vehicle_value>0));
CREATE TABLE property_policy_details (policy_id INT PRIMARY KEY, property_address VARCHAR(255) NOT NULL, property_type ENUM('Residential','Commercial') NOT NULL, property_value DECIMAL(14,2) NOT NULL, contents_value DECIMAL(14,2) NOT NULL DEFAULT 0, contents_included BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(policy_id) REFERENCES policies(policy_id) ON DELETE CASCADE, CHECK(property_value>0), CHECK(contents_value>=0));
CREATE TABLE life_policy_details (policy_id INT PRIMARY KEY, age_at_inception TINYINT NOT NULL, occupation VARCHAR(100), beneficiary_name VARCHAR(120) NOT NULL, beneficiary_contact VARCHAR(60) NOT NULL, FOREIGN KEY(policy_id) REFERENCES policies(policy_id) ON DELETE CASCADE, CHECK(age_at_inception BETWEEN 18 AND 65));
CREATE TABLE health_policy_details (policy_id INT PRIMARY KEY, health_plan ENUM('Basic','Standard','Premium') NOT NULL, dependants TINYINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(policy_id) REFERENCES policies(policy_id) ON DELETE CASCADE);
CREATE TABLE claims (claim_id INT AUTO_INCREMENT PRIMARY KEY, claim_number VARCHAR(40) NOT NULL UNIQUE, policy_id INT NOT NULL, customer_id INT NOT NULL, date_submitted DATE NOT NULL, claim_amount DECIMAL(14,2) NOT NULL, description TEXT NOT NULL, status ENUM('SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','PAID') NOT NULL DEFAULT 'SUBMITTED', approved_amount DECIMAL(14,2) NULL, rejection_reason VARCHAR(500), beneficiary_name VARCHAR(120), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(policy_id) REFERENCES policies(policy_id), FOREIGN KEY(customer_id) REFERENCES customers(customer_id), CHECK(claim_amount>0), CHECK(approved_amount IS NULL OR approved_amount>=0), CHECK(status<>'REJECTED' OR rejection_reason IS NOT NULL));
CREATE TABLE claim_assessments (assessment_id INT AUTO_INCREMENT PRIMARY KEY, claim_id INT NOT NULL, assessed_by INT NOT NULL, assessment_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, decision ENUM('APPROVED','REJECTED') NOT NULL, approved_amount DECIMAL(14,2), assessment_notes TEXT, rejection_reason VARCHAR(500), FOREIGN KEY(claim_id) REFERENCES claims(claim_id), FOREIGN KEY(assessed_by) REFERENCES users(user_id), CHECK(approved_amount IS NULL OR approved_amount>=0), CHECK(decision<>'REJECTED' OR rejection_reason IS NOT NULL));
CREATE INDEX idx_policies_customer ON policies(customer_id); CREATE INDEX idx_policies_status ON policies(status); CREATE INDEX idx_claims_status ON claims(status); CREATE INDEX idx_claims_policy ON claims(policy_id);
